import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync, readdirSync } from 'node:fs'
import sections from '../config/sections.js'
import { LANGUAGES, displayLocale } from './languages.js'

// Every translation file that exists — hand-written or generated by scripts/translate-locales.mjs
const LOCALE_FILES = readdirSync(new URL('./locales/', import.meta.url)).filter(f => f.endsWith('.json')).map(f => f.replace('.json', ''))

const load = code => JSON.parse(readFileSync(new URL(`./locales/${code}.json`, import.meta.url), 'utf8'))

function keys(obj, prefix = '') {
  return Object.entries(obj).flatMap(([k, v]) => (v && typeof v === 'object' ? keys(v, `${prefix}${k}.`) : [`${prefix}${k}`]))
}

test('every language has exactly the English keys', () => {
  const en = keys(load('en')).sort()
  for (const code of LOCALE_FILES) {
    const other = keys(load(code)).sort()
    const missing = en.filter(k => !other.includes(k))
    const extra = other.filter(k => !en.includes(k))
    assert.deepEqual(missing, [], `${code} is missing keys`)
    assert.deepEqual(extra, [], `${code} has unknown keys`)
  }
})

test('translations keep interpolation placeholders', () => {
  const en = load('en')
  const flat = (o, p = '') => Object.entries(o).flatMap(([k, v]) => (typeof v === 'object' ? flat(v, `${p}${k}.`) : [[`${p}${k}`, v]]))
  const enMap = Object.fromEntries(flat(en))
  for (const code of LOCALE_FILES) {
    for (const [k, v] of flat(load(code))) {
      const want = (enMap[k].match(/\{\{\w+\}\}/g) || []).sort()
      const got = (v.match(/\{\{\w+\}\}/g) || []).sort()
      assert.deepEqual(got, want, `${code}:${k} placeholders`)
    }
  }
})

test('English navigation covers every section and tab', () => {
  const nav = load('en').nav
  for (const s of sections) {
    assert.equal(nav.sections[s.id], s.label, `section ${s.id}`)
    for (const t of s.tabs) assert.equal(nav.tabs[s.id]?.[t.id], t.label, `tab ${s.id}/${t.id}`)
  }
})

test('display locale combines language and company country', () => {
  assert.equal(displayLocale('en', 'en-IN'), 'en-IN')
  assert.equal(displayLocale('fr', 'en-CA'), 'fr-CA-u-nu-latn')
  assert.equal(displayLocale('de', 'en-GB'), 'de-GB-u-nu-latn')
  assert.equal(displayLocale('ar', 'en-AE'), 'ar-AE-u-nu-latn')
  // Arabic amounts keep Latin digits
  assert.equal(new Intl.NumberFormat(displayLocale('ar', 'en-AE')).format(1234.5), '1,234.5')
})

test('every Google Translate language is listed with a name and direction', () => {
  assert.ok(LANGUAGES.length >= 130, 'covers the Google Translate language set')
  for (const l of LANGUAGES) {
    assert.ok(l.name && l.englishName, `${l.code} has names`)
    assert.ok(['ltr', 'rtl'].includes(l.dir))
  }
  assert.equal(LANGUAGES.find(l => l.code === 'he').dir, 'rtl')
  assert.equal(LANGUAGES.find(l => l.code === 'ur').dir, 'rtl')
  // every translation file belongs to a listed language
  for (const code of LOCALE_FILES) assert.ok(LANGUAGES.some(l => l.code === code), `${code} is a known language`)
})

test('display locale pins Latin digits for non-English languages', () => {
  assert.equal(new Intl.NumberFormat(displayLocale('bn', 'en-IN')).format(1234), '1,234')
  assert.equal(new Intl.NumberFormat(displayLocale('fa', 'en-AE')).format(1234), '1,234')
  assert.ok(displayLocale('zh-CN', 'en-IN').startsWith('zh-CN'))
})
